    private final int windowBits,mainElements;private final byte[] window;private final int windowMask;private int windowPos;private int r0=1,r1=1,r2=1,blockType,blockRemaining;private boolean headerRead,blockLengthOdd;private int intelFileSize;private boolean intelStarted;private int frameCount;private final byte[] mainLens;private final byte[] lengthLens=new byte[250],alignedLens=new byte[8];private final Huff mainTree=new Huff(),lengthTree=new Huff(),alignedTree=new Huff(),pretree=new Huff();private byte[] in;private int inPos;private long buf;private int cnt;
